import React from 'react';

// --- MOCK DATA STRUCTURES ---

interface Project {
  id: number;
  title: string;
  description: string;
  tags: string[];
}

const MOCK_PROJECTS: Project[] = [
  {
    id: 1,
    title: 'E-Commerce Platform',
    description: 'A full-stack solution built with React and Node.js, featuring Stripe integration and secure user authentication.',
    tags: ['React', 'Node.js', 'MongoDB', 'API'],
  },
  {
    id: 2,
    title: 'Real-Time Chat App',
    description: 'A high-performance chat application utilizing WebSockets for instant message delivery and presence indicators.',
    tags: ['WebSocket', 'Express', 'Socket.io', 'Real-Time'],
  },
  {
    id: 3,
    title: 'Data Visualization Dashboard',
    description: 'An interactive dashboard that consumes large datasets and presents complex information through dynamic charts.',
    tags: ['D3.js', 'Python', 'Data Science', 'Visualization'],
  },
  {
    id: 4,
    title: 'Serverless API Gateway',
    description: 'A scalable backend built entirely on AWS Lambda, providing robust and cost-effective API endpoints.',
    tags: ['AWS', 'Lambda', 'Serverless', 'Cloud'],
  },
];

// --- SUB-COMPONENTS ---

/**
 * Renders a single project card.
 */
const ProjectCard: React.FC<{ project: Project }> = ({ project }) => (
  <div className="p-6 bg-white shadow-lg rounded-xl transition duration-300 hover:shadow-2xl border border-gray-100 flex flex-col h-full">
    <h3 className="text-xl font-bold text-gray-900 mb-3">{project.title}</h3>
    <p className="text-gray-600 mb-4 flex-grow">{project.description}</p>
    <div className="flex flex-wrap gap-2 mt-auto pt-4 border-t border-gray-100">
      {project.tags.map((tag) => (
        <span key={tag} className="px-3 py-1 text-xs font-medium text-indigo-700 bg-indigo-100 rounded-full">
          {tag}
        </span>
      ))}
    </div>
  </div>
);

/**
 * Renders the grid layout for all projects.
 */
const ProjectsGrid: React.FC = () => (
  <section className="py-20 bg-gray-50" id="projects">
    <div className="container mx-auto px-6 max-w-6xl">
      <h2 className="text-4xl font-extrabold text-center text-gray-900 mb-4">
        Featured Projects
      </h2>
      <p className="text-center text-lg text-gray-600 mb-12">
        A showcase of my technical skills and problem-solving abilities.
      </p>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
        {MOCK_PROJECTS.map((project) => (
          <ProjectCard key={project.id} project={project} />
        ))}
      </div>
    </div>
  </section>
);

/**
 * Renders the professional summary section.
 */
const AboutSection: React.FC = () => (
  <section className="py-20 bg-white" id="about">
    <div className="container mx-auto px-6 max-w-4xl">
      <h2 className="text-4xl font-extrabold text-center text-gray-900 mb-4">
        About Me
      </h2>
      <p className="text-center text-lg text-gray-600 mb-10">
        I am a passionate Full Stack Developer specializing in building robust, scalable, and high-performance web applications.
      </p>

      <div className="text-lg text-gray-700 leading-relaxed space-y-6">
        <p>
          My expertise lies in the MERN stack (MongoDB, Express, React, Node.js), complemented by strong skills in cloud infrastructure (AWS) and modern frontend frameworks. I thrive in environments where complex problems require creative, technical solutions.
        </p>
        <p>
          I am committed to writing clean, maintainable code and continuously learning new technologies to deliver exceptional user experiences. Whether it's optimizing database queries or perfecting UI responsiveness, I bring dedication and precision to every project.
        </p>
        <p className="font-semibold text-indigo-600">
          Let's build something impactful together.
        </p>
      </div>
    </div>
  </section>
);

/**
 * Renders the initial introduction and Call To Action.
 */
const HeroSection: React.FC = () => (
  <header className="bg-gray-900 text-white py-24 text-center shadow-xl" id="hero">
    <div className="container mx-auto px-6 max-w-3xl">
      <h1 className="text-5xl md:text-6xl font-extrabold mb-4 leading-tight">
        Hi, I'm [Your Name]. I build things.
      </h1>
      <p className="text-xl md:text-2xl text-indigo-300 mb-8">
        A dedicated Full Stack Developer crafting seamless digital experiences from concept to deployment.
      </p>
      <div className="flex justify-center space-x-4">
        <button className="px-8 py-3 text-lg font-medium bg-indigo-600 text-white rounded-full shadow-lg hover:bg-indigo-700 transition duration-300 transform hover:scale-105">
          View Projects
        </button>
        <button className="px-8 py-3 text-lg font-medium border-2 border-white text-white rounded-full hover:bg-white hover:text-gray-900 transition duration-300">
          Get In Touch
        </button>
      </div>
    </div>
  </header>
);

/**
 * Renders the contact form/links section.
 */
const ContactSection: React.FC = () => {
